// Rank the talks by their votes, most first.
fn rank(talks: &mut Vec<Talk>) {
	talks.sort_by(|a, b| b.votes.cmp(&a.votes));
}

fn main() {
	let mut talks = load("talks.csv");
	rank(&mut talks);
	for (place, talk) in talks.iter().enumerate() {
		println!("{}. {}", place + 1, talk.title);
	}
	let top = talks.first().map(|t| t.title.as_str());
	println!("First: {}", top.unwrap_or("none"));
	let total: u32 = talks.iter().map(|t| t.votes).sum();
	println!("{} votes in all", total);
}
